import{_ as i,o as e,c as r,a0 as a}from"./chunks/framework.L_oL6aia.js";const h=JSON.parse('{"title":"二、快速使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/karing.md","filePath":"guide/karing.md"}'),s={name:"guide/karing.md"};function p(n,t,g,o,c,d){return e(),r("div",null,[...t[0]||(t[0]=[a('<p>本教程将引导您安装并配置 <strong>Karing 客户端</strong>。</p><p>Karing 是一款支持 <strong>Windows、Android、macOS、iOS</strong> 多平台的网络代理工具，各平台界面与操作逻辑基本一致。</p><hr><h2 id="一、软件下载" tabindex="-1">一、软件下载 <a class="header-anchor" href="#一、软件下载" aria-label="Permalink to &quot;一、软件下载&quot;">​</a></h2><p>请根据您的设备系统，选择对应的安装包进行下载：</p><table tabindex="0"><thead><tr><th style="text-align:left;">操作系统</th><th style="text-align:left;">适用设备/芯片</th><th style="text-align:left;">下载文件名</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows</strong></td><td style="text-align:left;">64位通用</td><td style="text-align:left;"><code>karing_windows_x64.exe</code></td></tr><tr><td style="text-align:left;"><strong>Android</strong></td><td style="text-align:left;">安卓手机 / 平板</td><td style="text-align:left;"><code>karing_android.apk</code></td></tr><tr><td style="text-align:left;"><strong>macOS</strong></td><td style="text-align:left;">Intel 芯片</td><td style="text-align:left;"><code>karing_macos.dmg</code></td></tr><tr><td style="text-align:left;"><strong>macOS / iOS</strong></td><td style="text-align:left;">Apple Silicon（M系列）/ iPhone / iPad</td><td style="text-align:left;">登录美区 Apple ID，前往 App Store 搜索 <strong>Karing</strong> 下载</td></tr></tbody></table><blockquote><p><strong>💡 大陆用户下载提示</strong></p><p>如官方网站访问较慢，可使用高速下载通道：</p><p><a href="https://doc.xhyjs.top/" target="_blank" rel="noreferrer">https://doc.xhyjs.top/</a></p></blockquote><h2 id="本教程以-windows-端-为例进行演示-其他平台操作方式基本相同。请根据您的设备系统-选择对应的安装包进行下载" tabindex="-1">本教程以 <strong>Windows 端</strong> 为例进行演示，其他平台操作方式基本相同。请根据您的设备系统，选择对应的安装包进行下载 <a class="header-anchor" href="#本教程以-windows-端-为例进行演示-其他平台操作方式基本相同。请根据您的设备系统-选择对应的安装包进行下载" aria-label="Permalink to &quot;本教程以 **Windows 端** 为例进行演示，其他平台操作方式基本相同。请根据您的设备系统，选择对应的安装包进行下载&quot;">​</a></h2><h1 id="二、快速使用指南" tabindex="-1">二、快速使用指南 <a class="header-anchor" href="#二、快速使用指南" aria-label="Permalink to &quot;二、快速使用指南&quot;">​</a></h1><h2 id="step-1-基础初始化设置" tabindex="-1">Step 1. 基础初始化设置 <a class="header-anchor" href="#step-1-基础初始化设置" aria-label="Permalink to &quot;Step 1. 基础初始化设置&quot;">​</a></h2><p>下载完成后，双击打开 <code>karing_windows_x64.exe</code> 安装包。</p><img src="https://doc.mimy.cc/gykaring11.webp" width="600" alt="基础初始化设置 01"><img src="https://doc.mimy.cc/gykaring22.webp" width="600" alt="基础初始化设置 02"><img src="https://doc.mimy.cc/gykaring33.webp" width="600" alt="基础初始化设置 03"><img src="https://doc.mimy.cc/gykaring44.webp" width="600" alt="基础初始化设置 04"><img src="https://doc.mimy.cc/gykaring55.webp" width="600" alt="基础初始化设置 05"><img src="https://doc.mimy.cc/gykaring66.webp" width="600" alt="基础初始化设置 06"><img src="https://doc.mimy.cc/gykaring77.webp" width="600" alt="基础初始化设置 07"><img src="https://doc.mimy.cc/gykaring88.webp" width="600" alt="基础初始化设置 08"><p>首次启动 Karing 时，会进入新手引导流程，请按照以下步骤完成基础设置：</p><p>1、 在地区选择界面选择 <strong>中国（China）</strong>。</p><p>2、 点击 <strong>下一步</strong>。</p><p>3、 根据提示开启 <strong>新手模式</strong>。</p><img src="https://doc.mimy.cc/gykaring111.webp" width="600" alt="基础初始化设置 09"><img src="https://doc.mimy.cc/gykaring222.webp" width="600" alt="基础初始化设置 10"><img src="https://doc.mimy.cc/gykaring333.webp" width="600" alt="基础初始化设置 11"><img src="https://doc.mimy.cc/gykaring444.webp" width="600" alt="基础初始化设置 12"><img src="https://doc.mimy.cc/gykaring555.webp" width="600" alt="基础初始化设置 13"><img src="https://doc.mimy.cc/gykaring666.webp" width="600" alt="基础初始化设置 14"><hr><h2 id="step-2-导入订阅地址" tabindex="-1">Step 2. 导入订阅地址 <a class="header-anchor" href="#step-2-导入订阅地址" aria-label="Permalink to &quot;Step 2. 导入订阅地址&quot;">​</a></h2><p>完成基础设置后，需要将您的订阅链接导入 Karing，以获取服务器节点。</p><p>操作步骤：</p><p>1、 登录 <strong>fangqi官网</strong>，复制您的订阅地址。</p><p>2、 打开 Karing 客户端，在 <strong>配置管理</strong> 页面选择 <strong>从剪切板导入</strong>。</p><p>3、 软件会自动识别复制的订阅链接。</p><p>4、 在 <strong>备注</strong> 栏输入：fangqi</p><p>5、 点击右上角 <strong><code>✓</code> 保存</strong> 按钮。</p><p><img src="https://img.mimy.cc/fangqi0303.webp" alt="图片描述"></p><p><img src="https://img.mimy.cc/fangqi0404.webp" alt="图片描述"></p><img src="https://doc.mimy.cc/gykaring999.webp" width="600" alt="配置管理界面"><img src="https://img.mimy.cc/fangqiK111.webp" width="600" alt="从剪切板导入示例"><hr><h2 id="step-3-节点选择与延迟测试" tabindex="-1">Step 3. 节点选择与延迟测试 <a class="header-anchor" href="#step-3-节点选择与延迟测试" aria-label="Permalink to &quot;Step 3. 节点选择与延迟测试&quot;">​</a></h2><p>成功导入订阅后，建议连接前进行一次节点延迟测试，选择速度更快、更稳定的线路。</p><p>操作步骤：</p><p>1、 点击左上角 <strong>返回</strong>，回到主界面。</p><p>2、 点击屏幕底部的 <strong><code>&gt;</code>（进入）</strong> 按钮，进入节点列表。</p><p>3、 点击展开按钮，显示全部节点。</p><p>4、 点击 <strong>闪电图标</strong>，进行全局延迟测试。</p><p>测试结果说明：</p><ul><li><strong>数值越低</strong>：表示网络延迟越小，连接速度通常越快。</li><li><strong>⚠️ 三角提示</strong>：表示该节点当前连接异常，可能暂时不可用。</li></ul><p>其他操作：</p><p>5、 如需测试单个节点，可点击节点后方的 <strong>三角形</strong> 或 <strong>数字标志</strong>。</p><p>6、 测试完成后，点击选择您需要使用的节点。</p><img src="https://doc.mimy.cc/xhykaring22.webp" width="600" alt="返回主界面"><img src="https://doc.mimy.cc/xhykaring33.webp" width="600" alt="进入节点列表"><img src="https://img.mimy.cc/fangqiK222.webp" width="600" alt="节点展开与延迟测试"><img src="https://doc.mimy.cc/xhykaring66.webp" width="600" alt="选择目标节点"><hr><h2 id="step-4-开启代理服务" tabindex="-1">Step 4. 开启代理服务 <a class="header-anchor" href="#step-4-开启代理服务" aria-label="Permalink to &quot;Step 4. 开启代理服务&quot;">​</a></h2><p>选择好节点后，即可开启系统代理。</p><p>操作步骤：</p><p>1、 点击左上角 <strong>返回</strong> 回到主界面。</p><p>2、 点击屏幕中央下方的 <strong>电源开关按钮</strong>。</p><p>3、 开启成功后：</p><ul><li>状态会由红色 <strong><code>✕</code></strong> 变为绿色 <strong><code>✓</code></strong>。</li><li>下方会显示当前使用的节点名称。</li></ul><p>此时，Karing 已成功连接。</p><img src="https://img.mimy.cc/fangqiK444.webp" width="600" alt="开启代理服务"><hr><h2 id="step-5-日常维护-更新订阅" tabindex="-1">Step 5. 日常维护：更新订阅 <a class="header-anchor" href="#step-5-日常维护-更新订阅" aria-label="Permalink to &quot;Step 5. 日常维护：更新订阅&quot;">​</a></h2><p>当服务器节点更新，或者需要同步套餐剩余流量时，可以手动更新订阅。</p><p>操作步骤：</p><p>1、 在主界面进入 <strong>我的配置</strong>。</p><p>2、 找到已添加的配置。</p><p>3、 点击右侧 <strong>云朵图标（更新）</strong>。</p><p>4、 等待同步完成即可获取最新节点信息。</p><img src="https://img.mimy.cc/fangqiK555.webp" width="600" alt="我的配置界面"><img src="https://img.mimy.cc/fangqiK666.webp" width="600" alt="更新订阅">',79)])])}const m=i(s,[["render",p]]);export{h as __pageData,m as default};
